#!/usr/bin/env python3
import sys, os, re, html as htmlmod
from html.parser import HTMLParser
from urllib.parse import urljoin

VERSION = "htmlq 0.4.0"

VOID_TAGS = set('area base br col embed hr img input link meta param source track wbr command keygen menuitem'.split())
RAW_TEXT = set(['script','style'])
RCDATA = set(['title','textarea'])
HEAD_TAGS = set(['base','basefont','bgsound','link','meta','title','noscript','noframes','style','script','template'])
P_CLOSE_ON = set('address article aside blockquote div dl fieldset footer form h1 h2 h3 h4 h5 h6 header hgroup hr main nav ol p pre section table ul'.split())
LI_CLOSE_ON = set(['li'])
DTDD_CLOSE_ON = set(['dt','dd'])
OPTION_CLOSE_ON = set(['option','optgroup'])
CELL_TAGS = set(['td','th'])
LINK_TAGS = set(['a','area','link','base'])

class Node:
    __slots__ = ('kind','tag','attrs','children','parent','data')
    def __init__(self, kind, tag=None, attrs=None, data=''):
        self.kind = kind
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        self.parent = None
        self.data = data
    def append(self, child):
        child.parent = self
        self.children.append(child)
        return child
    def prev_element_sibling(self):
        if not self.parent: return None
        prev = None
        for c in self.parent.children:
            if c is self: return prev
            if c.kind == 'element': prev = c
        return None
    def next_element_sibling(self):
        if not self.parent: return None
        seen = False
        for c in self.parent.children:
            if c is self:
                seen = True
            elif seen and c.kind == 'element':
                return c
        return None

class TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.doc = Node('document')
        self.html = self.doc.append(Node('element','html',{}))
        self.head = self.html.append(Node('element','head',{}))
        self.body = self.html.append(Node('element','body',{}))
        self.stack = [self.html]
        self.mode = 'before_head'  # before_head, in_head, after_head, in_body
        self.raw_stack = []
    def current(self):
        return self.stack[-1]
    def _lower_attrs(self, attrs):
        d = {}
        for k,v in attrs:
            if k is None: continue
            name = k.lower()
            d[name] = '' if v is None else htmlmod.unescape(v)
        return d
    def _merge_attrs(self, node, attrs):
        for k,v in attrs.items():
            if k not in node.attrs:
                node.attrs[k]=v
            else:
                node.attrs[k]=v
    def _ensure_body(self):
        if self.mode != 'in_body':
            self._pop_to(self.html)
            self.stack = [self.html, self.body]
            self.mode = 'in_body'
    def _ensure_head(self):
        if self.mode == 'before_head':
            self.stack = [self.html, self.head]
            self.mode = 'in_head'
        elif self.mode == 'after_head':
            self.stack = [self.html, self.head]
            self.mode = 'in_head'
    def _pop_to(self, node):
        while self.stack and self.stack[-1] is not node:
            self.stack.pop()
    def _find_open(self, tag):
        for i in range(len(self.stack)-1, -1, -1):
            if self.stack[i].kind == 'element' and self.stack[i].tag == tag:
                return i
        return -1
    def _close_tag_if_open(self, tag):
        i = self._find_open(tag)
        if i >= 0:
            self.stack = self.stack[:i]
            # if closing p, stack should exclude p but keep ancestors; i is index of p
            # correction: slice up to i excludes p
            if not self.stack:
                self.stack=[self.html]
            return True
        return False
    def _pop_until_inclusive(self, tag):
        i = self._find_open(tag)
        if i >= 0:
            self.stack = self.stack[:i]
            if not self.stack: self.stack=[self.html]
    def _auto_close_before(self, tag):
        if tag == 'p' or tag in P_CLOSE_ON:
            if self._find_open('p') >= 0:
                self._pop_until_inclusive('p')
        if tag in LI_CLOSE_ON:
            # close nearest open li if still in list scope (simple approximation)
            for i in range(len(self.stack)-1, -1, -1):
                if self.stack[i].kind=='element' and self.stack[i].tag=='li':
                    self.stack = self.stack[:i]
                    break
                if self.stack[i].kind=='element' and self.stack[i].tag in ('ul','ol'):
                    break
        if tag in DTDD_CLOSE_ON:
            for i in range(len(self.stack)-1, -1, -1):
                if self.stack[i].kind=='element' and self.stack[i].tag in ('dt','dd'):
                    self.stack = self.stack[:i]
                    break
        if tag in OPTION_CLOSE_ON:
            for i in range(len(self.stack)-1, -1, -1):
                if self.stack[i].kind=='element' and self.stack[i].tag=='option':
                    self.stack = self.stack[:i]
                    break
        if tag == 'tr':
            for i in range(len(self.stack)-1, -1, -1):
                if self.stack[i].kind=='element' and self.stack[i].tag=='tr':
                    self.stack = self.stack[:i]
                    break
                if self.stack[i].kind=='element' and self.stack[i].tag in ('table','tbody','thead','tfoot'):
                    break
        if tag in CELL_TAGS:
            for i in range(len(self.stack)-1, -1, -1):
                if self.stack[i].kind=='element' and self.stack[i].tag in CELL_TAGS:
                    self.stack = self.stack[:i]
                    break
                if self.stack[i].kind=='element' and self.stack[i].tag=='tr':
                    break
    def _insert_tbody_if_needed(self, tag):
        if tag == 'tr' and self.current().kind=='element' and self.current().tag == 'table':
            tb = self.current().append(Node('element','tbody',{}))
            self.stack.append(tb)
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs = self._lower_attrs(attrs)
        if tag == 'html':
            self._merge_attrs(self.html, attrs); self.stack=[self.html]; return
        if tag == 'head':
            self._merge_attrs(self.head, attrs); self.stack=[self.html,self.head]; self.mode='in_head'; return
        if tag == 'body':
            self._merge_attrs(self.body, attrs); self.stack=[self.html,self.body]; self.mode='in_body'; return
        if self.mode != 'in_body' and tag in HEAD_TAGS:
            self._ensure_head()
        else:
            self._ensure_body()
        self._auto_close_before(tag)
        self._insert_tbody_if_needed(tag)
        node = self.current().append(Node('element', tag, attrs))
        if tag not in VOID_TAGS:
            self.stack.append(node)
    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        tag = tag.lower()
        if tag not in VOID_TAGS:
            self.handle_endtag(tag)
    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in ('html','body'):
            if tag == 'body': self.stack=[self.html]
            return
        if tag == 'head':
            self.stack=[self.html]
            self.mode='after_head'
            return
        i = self._find_open(tag)
        if i >= 0:
            self.stack = self.stack[:i]
            if not self.stack: self.stack=[self.html]
            # after closing a head element we remain in head if head is open
            if self.mode == 'in_head' and self._find_open('head') < 0:
                self.stack=[self.html]
                self.mode='after_head'
    def handle_data(self, data):
        if data == '': return
        if self.mode != 'in_body' and self.current() is self.html and data.strip() == '':
            self._ensure_body()
        elif self.mode != 'in_body' and self.current() is self.html:
            self._ensure_body()
        self.current().append(Node('text', data=data))
    def handle_entityref(self, name):
        # In script/style HTMLParser normally gives raw text as data; elsewhere decode.
        self.handle_data(htmlmod.unescape('&'+name+';'))
    def handle_charref(self, name):
        self.handle_data(htmlmod.unescape('&#'+name+';'))
    def handle_comment(self, data):
        self._ensure_body() if self.mode == 'before_head' else None
        self.current().append(Node('comment', data=data))
    def handle_decl(self, decl):
        # Doctypes are not serialized by scraper/html5ever's selected html element.
        if decl.lower().startswith('doctype'):
            return
        self.handle_comment(decl)
    def handle_pi(self, data):
        # html5ever turns bogus processing instructions into comments without trailing ?
        if data.endswith('?'):
            data = data[:-1]
        self._ensure_body() if self.mode == 'before_head' else None
        self.current().append(Node('comment', data='?'+data+'?'))
    def close(self):
        super().close()
        self.stack=[self.html]

def parse_html(s):
    p = TreeBuilder()
    try:
        p.feed(s)
        p.close()
    except Exception:
        pass
    return p.doc

# Serialization

def esc_text(s, raw=False):
    if raw:
        return s
    return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

def esc_attr(s):
    return s.replace('&','&amp;').replace('"','&quot;')

def serialize_attrs(node, base=None):
    attrs = dict(node.attrs)
    if base and node.tag in LINK_TAGS and 'href' in attrs:
        attrs['href'] = urljoin(base, attrs.get('href',''))
    out=''
    for k in sorted(attrs.keys()):
        out += f' {k}="{esc_attr(attrs[k])}"'
    return out

def serialize(node, base=None, top=True):
    if node.kind == 'text':
        raw = node.parent is not None and node.parent.kind=='element' and node.parent.tag in RAW_TEXT
        return esc_text(node.data, raw=raw)
    if node.kind == 'comment':
        return '<!--' + node.data + '-->'
    if node.kind == 'document':
        return ''.join(serialize(c, base, False) for c in node.children)
    if node.kind == 'element':
        b = base if top else None
        s = '<' + node.tag + serialize_attrs(node, b) + '>'
        if node.tag in VOID_TAGS:
            return s
        s += ''.join(serialize(c, base=None, top=False) for c in node.children)
        s += '</' + node.tag + '>'
        return s
    return ''

def text_nodes(node):
    if node.kind == 'text':
        yield node.data
    elif node.kind in ('element','document'):
        for c in node.children:
            yield from text_nodes(c)

# CSS selector parser/matcher
class ParseError(Exception): pass
class AttrSel:
    def __init__(self, name, op=None, val='', ci=False):
        self.name=name.lower(); self.op=op; self.val=val; self.ci=ci
class Pseudo:
    def __init__(self, name, arg=None): self.name=name.lower(); self.arg=arg
class Compound:
    def __init__(self):
        self.tag=None; self.id=None; self.classes=[]; self.attrs=[]; self.pseudos=[]
class ComplexSel:
    def __init__(self, parts): self.parts=parts  # [(combinator_to_left, compound)] left->right; first comb None

def css_unescape(s):
    def repl(m):
        x=m.group(1)
        if re.match(r'^[0-9a-fA-F]', x):
            x=x.strip()
            try: return chr(int(x,16))
            except Exception: return ''
        return x
    return re.sub(r'\\([0-9a-fA-F]{1,6}\s?|.)', repl, s)

def split_top(s, sep=','):
    res=[]; start=0; br=0; par=0; quote=None; esc=False
    for i,ch in enumerate(s):
        if esc: esc=False; continue
        if ch=='\\': esc=True; continue
        if quote:
            if ch==quote: quote=None
            continue
        if ch in ('"',"'"):
            quote=ch; continue
        if ch=='[': br+=1
        elif ch==']': br-=1
        elif ch=='(': par+=1
        elif ch==')': par-=1
        elif ch==sep and br==0 and par==0:
            res.append(s[start:i].strip()); start=i+1
    res.append(s[start:].strip())
    return [r for r in res if r!='']

def read_ident(s,i):
    start=i
    if i < len(s) and s[i]=='*': return '*', i+1
    while i < len(s):
        ch=s[i]
        if ch.isalnum() or ch in ['_','-'] or ord(ch)>127:
            i+=1
        elif ch=='\\' and i+1 < len(s):
            i+=2
        else:
            break
    if i==start: raise ParseError('ident')
    return css_unescape(s[start:i]), i

def parse_attr_content(content):
    i=0; n=len(content)
    while i<n and content[i].isspace(): i+=1
    name,i=read_ident(content,i)
    while i<n and content[i].isspace(): i+=1
    if i>=n: return AttrSel(name)
    op=None
    if content.startswith('~=',i) or content.startswith('|=',i) or content.startswith('^=',i) or content.startswith('$=',i) or content.startswith('*=',i):
        op=content[i:i+2]; i+=2
    elif content[i]=='=':
        op='='; i+=1
    else:
        raise ParseError('attr')
    while i<n and content[i].isspace(): i+=1
    if i<n and content[i] in ('"',"'"):
        q=content[i]; i+=1; start=i; val=''; esc=False
        while i<n:
            ch=content[i]
            if esc:
                val += '\\' + ch; esc=False; i+=1; continue
            if ch=='\\': esc=True; i+=1; continue
            if ch==q: break
            val += ch; i+=1
        if i<n and content[i]==q: i+=1
        val=css_unescape(val)
    else:
        start=i
        while i<n and not content[i].isspace(): i+=1
        val=css_unescape(content[start:i])
    while i<n and content[i].isspace(): i+=1
    ci=False
    if i<n:
        flag=content[i:].strip()
        if flag.lower()=='i': ci=True
    return AttrSel(name,op,val,ci)

def find_matching(s,i,opench,closech):
    depth=0; quote=None; esc=False
    for j in range(i,len(s)):
        ch=s[j]
        if esc: esc=False; continue
        if ch=='\\': esc=True; continue
        if quote:
            if ch==quote: quote=None
            continue
        if ch in ('"',"'"):
            quote=ch; continue
        if ch==opench: depth+=1
        elif ch==closech:
            depth-=1
            if depth==0: return j
    raise ParseError('unclosed')

def parse_compound(s):
    c=Compound(); i=0; n=len(s); first=True
    if n==0: raise ParseError('empty')
    while i<n:
        ch=s[i]
        if first and (ch=='*' or ch.isalpha() or ch=='_' or ch=='-' or ch=='\\' or ord(ch)>127):
            ident,i=read_ident(s,i)
            if ident!='*': c.tag=ident.lower()
            first=False; continue
        first=False
        if ch=='#':
            val,i=read_ident(s,i+1); c.id=val
        elif ch=='.':
            val,i=read_ident(s,i+1); c.classes.append(val)
        elif ch=='[':
            j=find_matching(s,i,'[',']')
            c.attrs.append(parse_attr_content(s[i+1:j])); i=j+1
        elif ch==':':
            # pseudo-element: accept by name but make it impossible
            if i+1<n and s[i+1]==':':
                name,i=read_ident(s,i+2); c.pseudos.append(Pseudo('unsupported'))
            else:
                name,i=read_ident(s,i+1)
                arg=None
                if i<n and s[i]=='(':
                    j=find_matching(s,i,'(',')')
                    arg=s[i+1:j].strip(); i=j+1
                c.pseudos.append(Pseudo(name,arg))
        else:
            raise ParseError('compound')
    return c

def tokenize_complex(s):
    tokens=[]; i=0; n=len(s); cur=''; br=par=0; quote=None; esc=False; pending_comb=None; saw_space=False
    while i<n:
        ch=s[i]
        if esc:
            cur += ch; esc=False; i+=1; continue
        if ch=='\\': cur+=ch; esc=True; i+=1; continue
        if quote:
            cur += ch
            if ch==quote: quote=None
            i+=1; continue
        if ch in ('"',"'"):
            quote=ch; cur+=ch; i+=1; continue
        if ch=='[': br+=1; cur+=ch; i+=1; continue
        if ch==']': br-=1; cur+=ch; i+=1; continue
        if ch=='(': par+=1; cur+=ch; i+=1; continue
        if ch==')': par-=1; cur+=ch; i+=1; continue
        if br==0 and par==0 and ch.isspace():
            if cur.strip():
                tokens.append((pending_comb, cur.strip()))
                cur=''; pending_comb=' '
            else:
                if tokens: pending_comb = pending_comb or ' '
            while i<n and s[i].isspace(): i+=1
            continue
        if br==0 and par==0 and ch in ('>','+','~'):
            if cur.strip():
                tokens.append((pending_comb, cur.strip()))
                cur=''
            pending_comb=ch
            i+=1
            while i<n and s[i].isspace(): i+=1
            continue
        cur += ch; i+=1
    if cur.strip(): tokens.append((pending_comb, cur.strip()))
    if not tokens: raise ParseError('empty selector')
    # first selector has no left combinator; if pending on first ignore? invalid otherwise
    parts=[]
    for idx,(comb,txt) in enumerate(tokens):
        if idx==0: comb=None
        if idx>0 and comb is None: comb=' '
        parts.append((comb, parse_compound(txt)))
    return ComplexSel(parts)

def parse_selector(s):
    groups=split_top(s, ',')
    if not groups: raise ParseError('empty')
    return [tokenize_complex(g) for g in groups]

def element_children(parent):
    return [c for c in parent.children if c.kind=='element'] if parent else []

def element_index(node, of_type=False, from_end=False):
    sibs = element_children(node.parent)
    if of_type:
        sibs=[x for x in sibs if x.tag==node.tag]
    if from_end:
        sibs=list(reversed(sibs))
    for i,x in enumerate(sibs,1):
        if x is node: return i
    return 0

def parse_nth(expr):
    e=''.join((expr or '').lower().split())
    if e=='odd': return (2,1)
    if e=='even': return (2,0)
    if 'n' in e:
        pre,post=e.split('n',1)
        if pre in ('','+'): a=1
        elif pre=='-': a=-1
        else: a=int(pre)
        if post=='': b=0
        else: b=int(post)
        return a,b
    return (0,int(e))

def nth_match(idx, expr):
    try: a,b=parse_nth(expr)
    except Exception: return False
    if a==0: return idx==b
    k_num=idx-b
    if a>0:
        return k_num>=0 and k_num%a==0
    else:
        return k_num<=0 and k_num%a==0

def attr_match(actual, sel):
    if actual is None: return False
    av=actual; vv=sel.val
    if sel.ci:
        av=av.lower(); vv=vv.lower()
    if sel.op is None: return True
    if sel.op=='=': return av==vv
    if sel.op=='~=': return vv in av.split()
    if sel.op=='|=': return av==vv or av.startswith(vv+'-')
    if sel.op=='^=': return av.startswith(vv)
    if sel.op=='$=': return av.endswith(vv)
    if sel.op=='*=': return vv in av
    return False

def is_empty(node):
    for c in node.children:
        if c.kind=='element': return False
        if c.kind=='text' and c.data!='': return False
    return True

def match_pseudo(node, p, root):
    name=p.name; arg=p.arg
    if name=='root': return node is root
    if name in ('link','any-link'):
        return node.tag in LINK_TAGS and 'href' in node.attrs
    if name=='visited': return False
    if name=='empty': return is_empty(node)
    if name=='first-child': return element_index(node)==1
    if name=='last-child': return element_index(node, from_end=True)==1
    if name=='only-child': return len(element_children(node.parent))==1
    if name=='first-of-type': return element_index(node, of_type=True)==1
    if name=='last-of-type': return element_index(node, of_type=True, from_end=True)==1
    if name=='only-of-type': return len([x for x in element_children(node.parent) if x.tag==node.tag])==1
    if name=='nth-child': return nth_match(element_index(node), arg)
    if name=='nth-last-child': return nth_match(element_index(node, from_end=True), arg)
    if name=='nth-of-type': return nth_match(element_index(node, of_type=True), arg)
    if name=='nth-last-of-type': return nth_match(element_index(node, of_type=True, from_end=True), arg)
    if name=='not':
        try:
            sels=parse_selector(arg or '')
            return not any(match_complex(node, s, root) for s in sels)
        except Exception:
            return False
    if name in ('is','matches','where'):
        try:
            sels=parse_selector(arg or '')
            return any(match_complex(node, s, root) for s in sels)
        except Exception:
            return False
    if name=='checked': return 'checked' in node.attrs or 'selected' in node.attrs
    if name=='disabled': return 'disabled' in node.attrs
    if name=='enabled': return 'disabled' not in node.attrs
    return False

def match_compound(node, comp, root):
    if node.kind!='element': return False
    if comp.tag and node.tag.lower()!=comp.tag.lower(): return False
    if comp.id is not None and node.attrs.get('id','') != comp.id: return False
    classes = node.attrs.get('class','').split()
    for cl in comp.classes:
        if cl not in classes: return False
    for a in comp.attrs:
        # attr names are ASCII-insensitive in html
        val=None
        for k,v in node.attrs.items():
            if k.lower()==a.name.lower(): val=v; break
        if not attr_match(val, a): return False
    for p in comp.pseudos:
        if not match_pseudo(node,p,root): return False
    return True

def ancestors(node):
    p=node.parent
    while p is not None:
        if p.kind=='element': yield p
        p=p.parent

def match_complex_at(node, parts, idx, root):
    comb, comp = parts[idx]
    if not match_compound(node, comp, root): return False
    if idx==0: return True
    c = comb or ' '
    if c==' ':
        return any(match_complex_at(a, parts, idx-1, root) for a in ancestors(node))
    if c=='>':
        return node.parent is not None and node.parent.kind=='element' and match_complex_at(node.parent, parts, idx-1, root)
    if c=='+':
        p=node.prev_element_sibling()
        return p is not None and match_complex_at(p, parts, idx-1, root)
    if c=='~':
        p=node.prev_element_sibling()
        while p is not None:
            if match_complex_at(p, parts, idx-1, root): return True
            p=p.prev_element_sibling()
        return False
    return False

def match_complex(node, sel, root):
    return match_complex_at(node, sel.parts, len(sel.parts)-1, root)

def iter_elements(node):
    if node.kind=='element':
        yield node
    for c in node.children:
        if c.kind in ('element','document'):
            yield from iter_elements(c)

def select(doc, selector):
    root = None
    for e in iter_elements(doc):
        if e.tag=='html': root=e; break
    groups = parse_selector(selector)
    out=[]
    for e in iter_elements(doc):
        if any(match_complex(e,g,root) for g in groups):
            out.append(e)
    return out

# Pretty printer: approximates htmlq's pretty serialization.
def has_element_child(node): return any(c.kind=='element' for c in node.children)
def only_text_children(node): return all(c.kind!='element' for c in node.children)
def pretty_node(node, base=None, top=True, depth=0):
    if node.kind=='text':
        raw=node.parent is not None and node.parent.kind=='element' and node.parent.tag in RAW_TEXT
        return esc_text(node.data, raw=raw)
    if node.kind=='comment': return '<!--'+node.data+'-->'
    if node.kind!='element': return ''.join(pretty_node(c,base,False,depth) for c in node.children)
    b = base if top else None
    open_tag='<'+node.tag+serialize_attrs(node,b)+'>'
    if node.tag in VOID_TAGS: return open_tag
    if not node.children:
        return open_tag+'\n'+'  '*depth+'</'+node.tag+'>'
    if only_text_children(node):
        return open_tag+''.join(pretty_node(c,None,False,depth+1) for c in node.children)+'\n'+'  '*depth+'</'+node.tag+'>'
    # inline if mixed text with elements and no block-like element children
    if any(c.kind=='text' and c.data for c in node.children) and not any(c.kind=='element' and c.tag not in ('a','abbr','b','bdi','bdo','br','cite','code','em','i','img','span','strong','small','sub','sup','u') for c in node.children):
        return open_tag+''.join(pretty_node(c,None,False,depth+1) for c in node.children)+'\n'+'  '*depth+'</'+node.tag+'>'
    s=open_tag
    for c in node.children:
        if c.kind=='text':
            if c.data=='': continue
            s+='\n'+'  '*(depth+1)+pretty_node(c,None,False,depth+1)
        else:
            s+='\n'+'  '*(depth+1)+pretty_node(c,None,False,depth+1)
    s+='\n'+'  '*depth+'</'+node.tag+'>'
    return s

def pretty_serialize(node, base=None):
    return '\n' + pretty_node(node, base=base, top=True, depth=0)

def detect_base_url(doc, fallback):
    for e in iter_elements(doc):
        if e.tag=='base' and 'href' in e.attrs:
            return e.attrs['href']
    return fallback

HELP = '''htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    executable [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]
'''

def parse_args(argv):
    opts={'text':False,'pretty':False,'ignore_ws':False,'detect_base':False,'attr':None,'base':None,'filename':None,'output':None,'remove':[],'selectors':[]}
    i=0; positional=False
    while i < len(argv):
        a=argv[i]
        if positional:
            opts['selectors'].append(a); i+=1; continue
        if a=='--':
            positional=True; i+=1; continue
        if a in ('-h','--help'):
            print(HELP, end=''); sys.exit(0)
        if a in ('-V','--version'):
            print(VERSION); sys.exit(0)
        if a in ('-t','--text'):
            opts['text']=True; i+=1; continue
        if a in ('-p','--pretty'):
            opts['pretty']=True; i+=1; continue
        if a in ('-w','--ignore-whitespace'):
            opts['ignore_ws']=True; i+=1; continue
        if a in ('-B','--detect-base'):
            opts['detect_base']=True; i+=1; continue
        if a in ('-a','--attribute','-b','--base','-f','--filename','-o','--output'):
            if i+1>=len(argv):
                sys.stderr.write(f"error: The argument '{a}' requires a value but none was supplied\n")
                sys.exit(1)
            val=argv[i+1]
            if a in ('-a','--attribute'): opts['attr']=val
            elif a in ('-b','--base'): opts['base']=val
            elif a in ('-f','--filename'): opts['filename']=val
            elif a in ('-o','--output'): opts['output']=val
            i+=2; continue
        if a in ('-r','--remove-nodes'):
            i+=1
            if i>=len(argv) or argv[i].startswith('-'):
                sys.stderr.write(f"error: The argument '{a}' requires at least one value but none was supplied\n")
                sys.exit(1)
            while i<len(argv) and argv[i] != '--' and not argv[i].startswith('-'):
                opts['remove'].append(argv[i]); i+=1
            continue
        if a.startswith('--'):
            sys.stderr.write(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [--] [selector]...\n\nFor more information try --help\n")
            sys.exit(1)
        if a.startswith('-') and a not in ('-',):
            # support short flag clusters crudely
            handled=True
            for ch in a[1:]:
                if ch=='t': opts['text']=True
                elif ch=='p': opts['pretty']=True
                elif ch=='w': opts['ignore_ws']=True
                elif ch=='B': opts['detect_base']=True
                elif ch=='V': print(VERSION); sys.exit(0)
                elif ch=='h': print(HELP,end=''); sys.exit(0)
                else: handled=False; break
            if handled: i+=1; continue
            sys.stderr.write(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [--] [selector]...\n\nFor more information try --help\n")
            sys.exit(1)
        opts['selectors'].append(a); i+=1
    return opts

def panic(msg, line=221):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at src/main.rs:{line}:10:\n{msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

def main(argv):
    opts=parse_args(argv)
    try:
        if opts['filename']:
            with open(opts['filename'],'r',encoding='utf-8') as f: data=f.read()
        else:
            data=sys.stdin.read()
    except OSError as e:
        panic(f'should have opened input file: {e}', line=196)
    doc=parse_html(data)
    base=opts['base']
    if opts['detect_base']:
        base=detect_base_url(doc, base)
    selector=' '.join(opts['selectors']).strip() if opts['selectors'] else 'html'
    try:
        selected=select(doc, selector)
        remove_sels=[parse_selector(r) for r in opts['remove']]
    except Exception:
        panic('Failed to parse CSS selector: ()', line=221)
    out=[]
    def has_remove(n):
        if not remove_sels: return False
        root=next((e for e in iter_elements(doc) if e.tag=='html'), None)
        for e in iter_elements(n):
            for groups in remove_sels:
                if any(match_complex(e,g,root) for g in groups): return True
        return False
    for node in selected:
        if has_remove(node):
            continue
        if opts['attr'] is not None:
            name=opts['attr'].lower(); val=None
            for k,v in node.attrs.items():
                if k.lower()==name: val=v; break
            if val is not None:
                if base and name=='href' and node.tag in LINK_TAGS:
                    val=urljoin(base,val)
                out.append(val+'\n')
        elif opts['text']:
            if opts['ignore_ws']:
                for t in text_nodes(node):
                    if t.strip()!='': out.append(t+'\n')
                out.append('\n')
            else:
                out.append(''.join(text_nodes(node))+'\n')
        else:
            if opts['pretty']:
                out.append(pretty_serialize(node, base=base)+'\n')
            else:
                out.append(serialize(node, base=base, top=True)+'\n')
    result=''.join(out)
    try:
        if opts['output']:
            with open(opts['output'],'w',encoding='utf-8') as f: f.write(result)
        else:
            sys.stdout.write(result)
    except OSError as e:
        panic(f'should have created output file: {e}', line=202)

if __name__=='__main__':
    main(sys.argv[1:])
